begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values ('52000000-0000-0000-0000-000000000001','services-0@example.test'),('52000000-0000-0000-0000-000000000002','services-1@example.test'),('52000000-0000-0000-0000-000000000003','services-2@example.test'),('52000000-0000-0000-0000-000000000004','services-3@example.test');
insert into businesses(id,name,slug) values ('51000000-0000-0000-0000-000000000001','Services A','services-test-a'),('51000000-0000-0000-0000-000000000002','Services B','services-test-b');
insert into business_members(business_id,user_id,role) values ('51000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000001','owner'),('51000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000002','admin'),('51000000-0000-0000-0000-000000000001','52000000-0000-0000-0000-000000000003','employee'),('51000000-0000-0000-0000-000000000002','52000000-0000-0000-0000-000000000004','owner'),('51000000-0000-0000-0000-000000000002','52000000-0000-0000-0000-000000000001','employee');
insert into services(id,business_id,name,duration_minutes,price_cents,updated_at) values ('53000000-0000-0000-0000-000000000001','51000000-0000-0000-0000-000000000001','A',30,1000,'2000-01-01'),('53000000-0000-0000-0000-000000000002','51000000-0000-0000-0000-000000000002','B',60,2000,'2000-01-01');
select ok((select relrowsecurity from pg_class where oid='public.services'::regclass), 'Services RLS enabled');
set local role authenticated;
set local "request.jwt.claim.sub" = '52000000-0000-0000-0000-000000000001';
select is((select count(*) from services where business_id='51000000-0000-0000-0000-000000000001'), 1::bigint, 'owner reads own catalog');
select lives_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000001','Created owner',15,0)$$, 'owner creates');
select lives_ok($$update services set name='Edited owner',description='Details',duration_minutes=45,price_cents=1234,is_active=false where id='53000000-0000-0000-0000-000000000001'$$, 'owner edits and deactivates');
select is((select row(name,description,duration_minutes,price_cents,is_active)::text from services where id='53000000-0000-0000-0000-000000000001'), '("Edited owner",Details,45,1234,f)', 'owner changes persist');
select lives_ok($$update services set is_active=true where id='53000000-0000-0000-0000-000000000001'$$, 'owner activates');
select ok((select is_active and updated_at > '2000-01-01'::timestamptz from services where id='53000000-0000-0000-0000-000000000001'), 'owner activation and timestamp persist');
select throws_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000002','Attack',30,0)$$,'42501',null,'owner cannot create in B');
with changed as (update services set name='Attack' where id='53000000-0000-0000-0000-000000000002' returning id) select is((select count(*) from changed),0::bigint,'owner cannot update B');
select throws_ok($$delete from services where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'owner cannot delete');
set local "request.jwt.claim.sub" = '52000000-0000-0000-0000-000000000002';
select is((select count(*) from services where business_id='51000000-0000-0000-0000-000000000001'), 2::bigint, 'admin reads own catalog');
select lives_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000001','Created admin',15,0)$$, 'admin creates');
select lives_ok($$update services set name='Edited admin',description='Details',duration_minutes=45,price_cents=1234,is_active=false where id='53000000-0000-0000-0000-000000000001'$$, 'admin edits and deactivates');
select is((select row(name,description,duration_minutes,price_cents,is_active)::text from services where id='53000000-0000-0000-0000-000000000001'), '("Edited admin",Details,45,1234,f)', 'admin changes persist');
select lives_ok($$update services set is_active=true where id='53000000-0000-0000-0000-000000000001'$$, 'admin activates');
select ok((select is_active and updated_at > '2000-01-01'::timestamptz from services where id='53000000-0000-0000-0000-000000000001'), 'admin activation and timestamp persist');
select throws_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000002','Attack',30,0)$$,'42501',null,'admin cannot create in B');
with changed as (update services set name='Attack' where id='53000000-0000-0000-0000-000000000002' returning id) select is((select count(*) from changed),0::bigint,'admin cannot update B');
select throws_ok($$delete from services where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'admin cannot delete');
set local "request.jwt.claim.sub" = '52000000-0000-0000-0000-000000000003';
select is((select count(*) from services where business_id='51000000-0000-0000-0000-000000000001'), 3::bigint, 'employee reads own catalog');
select throws_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000001','Blocked',30,0)$$,'42501',null,'Employee cannot create');
with changed as (update services set name='Blocked',is_active=false where id='53000000-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed),0::bigint,'Employee cannot edit or deactivate');
select throws_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000002','Attack',30,0)$$,'42501',null,'employee cannot create in B');
with changed as (update services set name='Attack' where id='53000000-0000-0000-0000-000000000002' returning id) select is((select count(*) from changed),0::bigint,'employee cannot update B');
select throws_ok($$delete from services where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'employee cannot delete');
set local "request.jwt.claim.sub" = '52000000-0000-0000-0000-000000000004';
select is((select count(*) from services),1::bigint,'B owner sees only B');
select is((select count(*) from services where id='53000000-0000-0000-0000-000000000001'),0::bigint,'Explicit ID cannot expose A');
with changed as (update services set is_active=false where id='53000000-0000-0000-0000-000000000001' returning id) select is((select count(*) from changed),0::bigint,'B owner cannot update A');
set local "request.jwt.claim.sub" = '52000000-0000-0000-0000-000000000001';
select throws_ok($$update services set business_id='51000000-0000-0000-0000-000000000002' where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'Tenant cannot be changed');
select throws_ok($$update services set updated_at='2000-01-01' where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'Timestamp cannot be forged');
select throws_ok($$update services set name=' ' where id='53000000-0000-0000-0000-000000000001'$$,'23514',null,'Blank name rejected');
select throws_ok($$update services set duration_minutes=0 where id='53000000-0000-0000-0000-000000000001'$$,'23514',null,'Zero duration rejected');
select throws_ok($$update services set price_cents=-1 where id='53000000-0000-0000-0000-000000000001'$$,'23514',null,'Negative price rejected');
reset role;
update business_members set role='owner' where business_id='51000000-0000-0000-0000-000000000002' and user_id='52000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$update services set business_id='51000000-0000-0000-0000-000000000002' where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'Even manager of both tenants cannot transfer services');
set local "request.jwt.claim.sub" = '';
select is((select count(*) from services),0::bigint,'Missing identity sees nothing');
reset role;
set local role anon;
select throws_ok($$select * from services$$,'42501',null,'Anonymous cannot read');
select throws_ok($$insert into services(business_id,name,duration_minutes,price_cents) values ('51000000-0000-0000-0000-000000000001','Anonymous',30,0)$$,'42501',null,'Anonymous cannot create');
select throws_ok($$update services set is_active=false where id='53000000-0000-0000-0000-000000000001'$$,'42501',null,'Anonymous cannot edit');
select throws_ok($$delete from services$$,'42501',null,'Anonymous cannot delete');
reset role;
select * from finish();
rollback;
